declare module '*.mp4' {
  const src: string;
  export default src;
}

declare module '*.webm' {
  const src: string;
  export default src;
}

declare module '*.ogg' {
  const src: string;
  export default src;
}

declare module 'figma:asset/*.mp4' {
  const src: string;
  export default src;
}

declare module 'figma:asset/*.webm' {
  const src: string;
  export default src;
}

declare module 'figma:asset/*.ogg' {
  const src: string;
  export default src;
}
